 11	// Uplay 1.5.0 — verify this address is the Uplay equivalent
 12	// before shipping; if it crashes revert DoSheathe() to a no-op
 13	DEFINE_GAME_FUNCTION(ReattachWeaponToSheathOrHolster, 0x141B05570,
 14	    void, __fastcall, (__int64 a1, int p_1melee2ranged));
 15
 16	// EquipWeapon leaf state addresses (same in both versions per agent research)
 17	static constexpr uint64_t ADDR_EQUIPWEAPON_EQUIPPING         = 0x141B03750;
 18	static constexpr uint64_t ADDR_EQUIPWEAPON_PENDINGTRANSITION = 0x141B04C30;
 19
 20	static bool IsStateActive(HumanStatesHolder& hs, uint64_t addr)
 21	{
 22	    for (auto& r : hs.primaryCallbackReceivers)
 23	        if (r.pNode && (uint64_t)r.pNode->Enter == addr)
 24	            return true;
 25	    return false;
 26	}
