 28	void ForceSheathePlugin::DoSheathe()
 29	{
 30	    Entity* player = ACU::GetPlayer();
 31	    if (!player) return;
 32	    ReattachWeaponToSheathOrHolster((__int64)player, 1);
 33	    ReattachWeaponToSheathOrHolster((__int64)player, 2);
 34	}
