 36	static std::string GetIniPath()
 37	{
 38	    char docs[MAX_PATH];
 39	    if (SUCCEEDED(SHGetFolderPathA(NULL, CSIDL_PERSONAL, NULL, 0, docs)))
 40	        return std::string(docs) + "\\Assassin's Creed Unity\\ForceSheathe.ini";
 41	    return "ForceSheathe.ini";
 42	}
