 44	void ForceSheathePlugin::LoadSettings()
 45	{
 46	    std::ifstream f(GetIniPath());
 47	    if (!f) return;
 48	    std::string line;
 49	    while (std::getline(f, line))
 50	    {
 51	        if (line.rfind("SheatheKey=", 0) == 0)
 52	            try { m_SheatheKey = std::stoi(line.substr(11), nullptr, 16); } catch (...) {}
 53	        if (line.rfind("PreventDrawKey=", 0) == 0)
 54	            try { m_PreventDrawKey = std::stoi(line.substr(15), nullptr, 16); } catch (...) {}
 55	        if (line.rfind("PreventDraw=", 0) == 0)
 56	            try { m_PreventDraw = std::stoi(line.substr(12)) != 0; } catch (...) {}
 57	    }
 58	}
 59
 60	void ForceSheathePlugin::SaveSettings()
 61	{
 62	    try {
 63	        std::ofstream f(GetIniPath());
 64	        if (f)
 65	            f << "SheatheKey=" << std::hex << m_SheatheKey << "\n"
 66	              << "PreventDrawKey=" << m_PreventDrawKey << "\n"
 67	              << std::dec << "PreventDraw=" << (m_PreventDraw ? 1 : 0) << "\n";
 68	    } catch (...) {}
 69	}
 70
 71	void ForceSheathePlugin::OnUpdate()
 72	{
 73	    // ── Rebind sheathe key ───────────────────────────────
 74	    if (m_WaitingForSheathe)
 75	    {
 76	        for (int vk = 0x08; vk <= 0xFE; ++vk)
 77	            if (GetAsyncKeyState(vk) & 0x8000)
 78	            {
 79	                m_SheatheKey = vk; m_WaitingForSheathe = false;
 80	                SaveSettings(); return;
 81	            }
 82	        return;
 83	    }
 84
 85	    // ── Rebind prevent-draw key ──────────────────────────
 86	    if (m_WaitingForDrawKey)
 87	    {
 88	        for (int vk = 0x08; vk <= 0xFE; ++vk)
 89	            if (GetAsyncKeyState(vk) & 0x8000)
 90	            {
 91	                m_PreventDrawKey = vk; m_WaitingForDrawKey = false;
 92	                SaveSettings(); return;
 93	            }
 94	        return;
 95	    }
 96
 97	    // ── Force sheathe — rising edge ──────────────────────
 98	    bool sheatheDown = (GetAsyncKeyState(m_SheatheKey) & 0x8000) != 0;
 99	    if (sheatheDown && !m_PrevSheatheKey)
100	        DoSheathe();
101	    m_PrevSheatheKey = sheatheDown;
102
103	    // ── Prevent draw toggle — rising edge ────────────────
104	    bool drawKeyDown = (GetAsyncKeyState(m_PreventDrawKey) & 0x8000) != 0;
105	    if (drawKeyDown && !m_PrevDrawKey)
106	    {
107	        m_PreventDraw = !m_PreventDraw;
108	        SaveSettings();
109	    }
110	    m_PrevDrawKey = drawKeyDown;
111
112	    // ── Prevent draw — cancel equip every frame ──────────
113	    if (m_PreventDraw)
114	    {
115	        HumanStatesHolder* hs = HumanStatesHolder::GetForPlayer();
116	        if (hs && (IsStateActive(*hs, ADDR_EQUIPWEAPON_EQUIPPING) ||
117	                   IsStateActive(*hs, ADDR_EQUIPWEAPON_PENDINGTRANSITION)))
118	            DoSheathe();
119	    }
120	}
