122	void ForceSheathePlugin::OnImGuiRender()
123	{
124	    if (!ImGui::CollapsingHeader("Force Sheathe"))
125	        return;
126
127	    // Force sheathe key
128	    ImGui::Text("Force Sheathe: 0x%02X", m_SheatheKey);
129	    ImGui::SameLine();
130	    if (ImGui::Button(m_WaitingForSheathe ? "Cancel##s" : "Rebind##s"))
131	        m_WaitingForSheathe = !m_WaitingForSheathe;
132	    if (m_WaitingForSheathe)
133	        ImGui::TextColored({1,1,0,1}, "Press any key...");
134
135	    ImGui::Separator();
136
137	    // Prevent draw toggle
138	    ImVec4 col = m_PreventDraw ? ImVec4(1,0.3f,0.3f,1) : ImVec4(0.5f,0.5f,0.5f,1);
139	    ImGui::TextColored(col, m_PreventDraw ? "Draw: LOCKED" : "Draw: unlocked");
140	    ImGui::Text("Toggle key: 0x%02X", m_PreventDrawKey);
141	    ImGui::SameLine();
142	    if (ImGui::Button(m_WaitingForDrawKey ? "Cancel##d" : "Rebind##d"))
143	        m_WaitingForDrawKey = !m_WaitingForDrawKey;
144	    if (m_WaitingForDrawKey)
145	        ImGui::TextColored({1,1,0,1}, "Press any key...");
146	}

